 "content": "def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Each diagonal pair identifies a ray; extend it in both directions to the edges.
    for color, n in counts.items():
        if color == bg or n < 2:
            continue
        pts = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color}
        for r, c in list(pts):
            for dr, dc in ((1, 1), (1, -1)):
                if (r + dr, c + dc) in pts:
                    rr, cc = r, c
                    while 0 <= rr - dr < len(out) and 0 <= cc - dc < len(out[0]):
                        rr -= dr; cc -= dc
                        if out[rr][cc] == bg: out[rr][cc] = color
                    rr, cc = r + dr, c + dc
                    while 0 <= rr + dr < len(out) and 0 <= cc + dc < len(out[0]):
                        rr += dr; cc += dc
                        if out[rr][cc] == bg: out[rr][cc] = color
    return out
